 62	    private static final class ActivitySchedule {
 63	        private final Activity[] activities;
 64	
 65	        private ActivitySchedule(Activity[] activities) {
 66	            this.activities = activities;
 67	        }
 68	
 69	        private static ActivitySchedule fromParallelArrays(int[] start, int[] finish) {
 70	            validateInputs(start, finish);
 71	
 72	            Activity[] activities = new Activity[start.length];
 73	            for (int i = 0; i < start.length; i++) {
 74	                activities[i] = new Activity(start[i], finish[i]);
 75	            }
 76	
 77	            Arrays.sort(activities, BY_FINISH_TIME);
 78	            return new ActivitySchedule(activities);
 79	        }
 80	
 81	        private SelectionResult selectionResult() {
 82	            Activity[] selectedActivities = selectCompatibleActivities();
 83	            int[][] selectedPairs = new int[selectedActivities.length][2];
 84	            for (int i = 0; i < selectedActivities.length; i++) {
 85	                selectedPairs[i] = selectedActivities[i].toPair();
 86	            }
 87	            return new SelectionResult(selectedPairs);
 88	        }
 89	
 90	        private Activity[] selectCompatibleActivities() {
 91	            if (activities.length == 0) {
 92	                return new Activity[0];
 93	            }
 94	
 95	            Activity[] selectedActivities = new Activity[activities.length];
 96	            int selectedCount = 1;
 97	            Activity lastSelected = activities[0];
 98	            selectedActivities[0] = lastSelected;
 99	
100	            // Greedily keep the earliest-finishing compatible activity.
101	            for (int i = 1; i < activities.length; i++) {
102	                Activity current = activities[i];
103	                if (current.canFollow(lastSelected)) {
104	                    selectedActivities[selectedCount] = current;
105	                    selectedCount++;
106	                    lastSelected = current;
107	                }
108	            }
109	
110	            return Arrays.copyOf(selectedActivities, selectedCount);
111	        }
