114	            Objects.requireNonNull(start, "start must not be null");
115	            Objects.requireNonNull(finish, "finish must not be null");
116	
117	            if (start.length != finish.length) {
118	                throw new IllegalArgumentException("start and finish must have the same length");
119	            }
120	        }
121	    }
