  4	    public static void main(String[] args) {
  5	        SelectionCase[] selectionCases = {
  6	            new SelectionCase(
  7	                4,
  8	                new int[] {1, 3, 0, 5, 8, 5},
  9	                new int[] {2, 4, 6, 7, 9, 9},
 10	                new int[][] {{1, 2}, {3, 4}, {5, 7}, {8, 9}},
 11	                "selects the expected number of compatible activities"
 12	            ),
 13	            new SelectionCase(
 14	                0,
 15	                new int[] {},
 16	                new int[] {},
 17	                new int[][] {},
 18	                "returns zero for empty input"
 19	            ),
 20	            new SelectionCase(
 21	                1,
 22	                new int[] {1, 2},
 23	                new int[] {2, 3},
 24	                new int[][] {{1, 2}},
 25	                "preserves the strict compatibility rule when activities touch"
 26	            )
 27	        };
 28	
 29	        for (SelectionCase testCase : selectionCases) {
 30	            assertSelectionCount(testCase);
 31	            assertSelectedActivities(testCase);
 32	            assertSelectionResult(testCase);
 33	            assertLegacyAlias(testCase);
 34	        }
 35	
 36	        assertThrows(
 37	            IllegalArgumentException.class,
 38	            () -> ActivitySelection.activitySelection(new int[] {1, 2}, new int[] {3}),
 39	            "rejects mismatched input lengths"
 40	        );
 41	
 42	        assertThrows(
 43	            NullPointerException.class,
 44	            () -> ActivitySelection.activitySelection(null, new int[] {}),
 45	            "rejects null start input"
 46	        );
 47	
 48	        assertThrows(
 49	            NullPointerException.class,
 50	            () -> ActivitySelection.activitySelection(new int[] {}, null),
 51	            "rejects null finish input"
 52	        );
 53	    }
