 55	    private static void assertLegacyAlias(SelectionCase testCase) {
 56	        assertEquals(
 57	            ActivitySelection.maximumCompatibleActivityCount(
 58	                testCase.startTimes(),
 59	                testCase.finishTimes()
 60	            ),
 61	            ActivitySelection.activitySelection(testCase.startTimes(), testCase.finishTimes()),
 62	            testCase.message() + " through the legacy alias"
 63	        );
 64	    }
