 66	    private static void assertSelectionResult(SelectionCase testCase) {
 67	        ActivitySelection.SelectionResult result =
 68	            ActivitySelection.buildSelectionResult(testCase.startTimes(), testCase.finishTimes());
 69	
 70	        assertEquals(
 71	            testCase.expectedCount(),
 72	            result.count(),
 73	            testCase.message() + " with the expected result count"
 74	        );
 75	        assertDeepEquals(
 76	            testCase.expectedActivities(),
 77	            result.activities(),
 78	            testCase.message() + " with the expected result activities"
 79	        );
 80	    }
