104	    private static void assertDeepEquals(int[][] expected, int[][] actual, String message) {
105	        if (!Arrays.deepEquals(expected, actual)) {
106	            throw new AssertionError(
107	                message
108	                    + ": expected "
109	                    + Arrays.deepToString(expected)
110	                    + " but got "
111	                    + Arrays.deepToString(actual)
112	            );
113	        }
114	    }
115	
116	    private static void assertEquals(int expected, int actual, String message) {
117	        if (expected != actual) {
118	            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
119	        }
120	    }
