122	    private static void assertThrows(
123	        Class<? extends Throwable> expected,
124	        ThrowingRunnable runnable,
125	        String message
126	    ) {
127	        try {
128	            runnable.run();
129	        } catch (Throwable actual) {
130	            if (expected.isInstance(actual)) {
131	                return;
132	            }
133	            throw new AssertionError(
134	                message + ": expected " + expected.getSimpleName() + " but got " + actual.getClass().getSimpleName(),
135	                actual
136	            );
137	        }
138	
139	        throw new AssertionError(message + ": expected " + expected.getSimpleName() + " to be thrown");
140	    }
